#!/usr/bin/env node
/* ─── build-engineering-symbols ─────────────────────────────────────────────
 * Reads assets/engineering/*.svg + manifest.json and emits an inline React
 * module (dcmoc/.../diagram/symbols.gen.ts) exporting, per equipment kind, the
 * INNER SVG markup (paths/shapes) as a JSX-safe fragment string. Strokes stay
 * `currentColor` so the diagram recolours by lane. The generated fragment is
 * rendered inside a <g> that translate/scales the 0..48 symbol to any size.
 *
 * Run: node tools/build-engineering-symbols.mjs
 * GENERATED FILE — do not hand-edit symbols.gen.ts; edit the SVGs instead.
 * ──────────────────────────────────────────────────────────────────────── */
import { readFileSync, writeFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SRC = join(ROOT, 'assets', 'engineering');
const OUT = join(ROOT, 'dcmoc', 'src', 'components', 'modules', 'architecture', 'diagram', 'symbols.gen.ts');
const OUT_JS = join(ROOT, 'js', 'rz-eng-symbols.js');
const VIEW = 48; // authored viewBox is 0 0 48 48

const manifest = JSON.parse(readFileSync(join(SRC, 'manifest.json'), 'utf8'));

/** Extract the inner markup of an <svg> (drop wrapper + XML/HTML comments). */
function innerSvg(svg) {
    let s = svg.replace(/<!--[\s\S]*?-->/g, '');           // comments
    const open = s.indexOf('<svg');
    const gt = s.indexOf('>', open);
    const close = s.lastIndexOf('</svg>');
    s = s.slice(gt + 1, close);
    // normalise attribute names to JSX camelCase so the string can drop into JSX via dangerouslySetInnerHTML-free inlining
    return s.trim();
}

/** kebab/HTML attributes → keep as-is: we inject via innerHTML-compatible string,
 * so standard SVG attribute names (stroke-width, text-anchor…) are correct. */

const kinds = Object.keys(manifest);
const entries = kinds.map((kind) => {
    const meta = manifest[kind];
    const raw = readFileSync(join(SRC, meta.file), 'utf8');
    const body = innerSvg(raw)
        .replace(/\s+/g, ' ')
        .replace(/> </g, '><')
        .trim();
    return { kind, meta, body };
});

/* DCMOC's NodeDetailModal keeps an exhaustive Record<SymbolKind, …>, so a kind
 * added for the static pages only must not widen the TypeScript union — it
 * would fail DCMOC's next build on a file nobody touched. `"dcmoc": false` in
 * the manifest keeps a symbol web-only. */
const tsEntries = entries.filter((e) => e.meta.dcmoc !== false);

const header = `/* AUTO-GENERATED by tools/build-engineering-symbols.mjs — DO NOT EDIT.
 * Source: assets/engineering/*.svg + manifest.json.
 * Per equipment kind: the inner SVG markup (IEC single-line-diagram symbols),
 * strokes = currentColor so the diagram recolours by lane. Authored in a
 * 0..${VIEW} coordinate box; SymbolGlyph translate/scales it to any size. */

export const SYMBOL_VIEWBOX = ${VIEW};

export type GenSymbolKind =
${tsEntries.map((e, i) => `    ${i === 0 ? '  ' : '| '}'${e.kind}'`).join('\n')};

export interface GenSymbolMeta { label: string; category: string }

export const SYMBOL_META: Record<GenSymbolKind, GenSymbolMeta> = {
${tsEntries.map((e) => `    ${e.kind}: { label: ${JSON.stringify(e.meta.label)}, category: ${JSON.stringify(e.meta.category)} },`).join('\n')}
};

/** Inner SVG markup per kind (paths/shapes only; currentColor strokes). */
export const SYMBOL_MARKUP: Record<GenSymbolKind, string> = {
${tsEntries.map((e) => `    ${e.kind}: ${JSON.stringify(e.body)},`).join('\n')}
};
`;

writeFileSync(OUT, header);
console.log(`symbols.gen.ts ← ${tsEntries.length} symbols (DCMOC)`);

/* The same library for the zero-build pages. One source (assets/engineering),
 * two emitters: DCMOC imports the TypeScript module, the static pages load this
 * script and the RZ diagram engine draws a node's `symbol` from it. A symbol
 * edited for one surface is edited for both. */
const js = `/* AUTO-GENERATED by tools/build-engineering-symbols.mjs — DO NOT EDIT.
 * Source: assets/engineering/*.svg + manifest.json (the library DCMOC uses).
 * IEC 60617 / ISA-5.1 / NFPA 170-style symbols, inner SVG markup authored in a
 * 0..${VIEW} box with currentColor strokes. Consumed by js/rz-diagram.js
 * (node option \`symbol\`) and by any page that inlines a glyph. */
(function (root) {
  'use strict';
  var API = {
    VIEW: ${VIEW},
    META: {
${entries.map((e) => `      ${e.kind}: { label: ${JSON.stringify(e.meta.label)}, category: ${JSON.stringify(e.meta.category)} }`).join(',\n')}
    },
    MARKUP: {
${entries.map((e) => `      ${e.kind}: ${JSON.stringify(e.body)}`).join(',\n')}
    },
    /* HMI fields (R128, PRD §4): standard, ports on the 6-unit grid, states, tag prefix. Only kinds that declare them. */
    STANDARD: {
${entries.filter((e) => e.meta.standard).map((e) => `      ${e.kind}: ${JSON.stringify(e.meta.standard)}`).join(',\n')}
    },
    PORTS: {
${entries.filter((e) => e.meta.ports).map((e) => `      ${e.kind}: ${JSON.stringify(e.meta.ports)}`).join(',\n')}
    },
    STATES: {
${entries.filter((e) => e.meta.states).map((e) => `      ${e.kind}: ${JSON.stringify(e.meta.states)}`).join(',\n')}
    },
    TAG: {
${entries.filter((e) => e.meta.tagPrefix !== undefined).map((e) => `      ${e.kind}: ${JSON.stringify(e.meta.tagPrefix)}`).join(',\n')}
    },
    /** A standalone <svg> for one kind, sized in CSS px. */
    svg: function (kind, size, cls) {
      var m = API.MARKUP[kind];
      if (!m) return '';
      var sz = size || 24;
      return '<svg class="' + (cls || 'rz-sym') + '" viewBox="0 0 ' + API.VIEW + ' ' + API.VIEW +
        '" width="' + sz + '" height="' + sz + '" fill="none" stroke="currentColor" stroke-width="2"' +
        ' stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + m + '</svg>';
    },
    /** Kinds, optionally of one category. */
    list: function (category) {
      return Object.keys(API.META).filter(function (k) { return !category || API.META[k].category === category; });
    },
    /** Named ports of a kind in drawing units: {name: {x, y, medium}} after scale + rotation about the symbol centre. */
    ports: function (kind, o) {
      var p = API.PORTS[kind], out = {}, s = (o && o.size || API.VIEW) / API.VIEW, r = ((o && o.rot) || 0) % 360;
      if (!p) return out;
      Object.keys(p).forEach(function (n) {
        var dx = p[n][0] - API.VIEW / 2, dy = p[n][1] - API.VIEW / 2, x = dx, y = dy;
        if (r === 90) { x = -dy; y = dx; } else if (r === 180) { x = -dx; y = -dy; } else if (r === 270) { x = dy; y = -dx; }
        out[n] = { x: ((o && o.x) || 0) + x * s, y: ((o && o.y) || 0) + y * s, medium: p[n][2] };
      });
      return out;
    },
    /** One placed symbol as an SVG group string. o = {x, y (centre), size, rot (0/90/180/270), state, tag, id, label}. */
    use: function (kind, o) {
      var m = API.MARKUP[kind];
      if (!m) return '';
      o = o || {};
      var sz = o.size || API.VIEW, s = sz / API.VIEW, h = sz / 2, esc = function (t) {
        return String(t).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; });
      };
      return '<g class="rz-hmi-sym" data-sym="' + kind + '"' + (o.id ? ' data-id="' + esc(o.id) + '"' : '') +
        (o.state ? ' data-state="' + esc(o.state) + '"' : '') +
        ' transform="translate(' + ((o.x || 0) - h) + ' ' + ((o.y || 0) - h) + ')' + (o.rot ? ' rotate(' + o.rot + ' ' + h + ' ' + h + ')' : '') +
        (s !== 1 ? ' scale(' + s + ')' : '') + '">' +
        '<g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + m + '</g></g>';
    }
  };
  root.RZEngSymbols = API;
  if (typeof module !== 'undefined' && module.exports) module.exports = API;
})(typeof window !== 'undefined' ? window : globalThis);
`;
writeFileSync(OUT_JS, js);
console.log(`js/rz-eng-symbols.js ← ${entries.length} symbols`);
